import math

def solve(wavelength=5.3, prf=900, true_velocity=19):
    # Constants
    c = 3e8  # Speed of light in m/s
    f = c / wavelength  # Frequency in Hz
    v = true_velocity  # True radial velocity in m/s

    # Nyquist velocity
    vn = c / (2 * prf * wavelength)  # in m/s

    # Determine the aliasing
    if v > vn:
        # Velocity is aliased, subtract 2*vn to bring it within the Nyquist range
        aliased_velocity = v - 2 * vn
    else:
        # No aliasing
        aliased_velocity = v

    return {
        "1": {"value": aliased_velocity, "unit": "m s^-1"}
    }
